# The default character normalization of the embedders (AbstractEmbedder.mapper): letters of the MUFI character set
# map to the most similar lower-case ASCII letter, whitespace to " ", punctuation and symbols to ".", decimal digits to
# their value, "-" to itself; anything else is unknown. MAPPING is generated by build_mapping() (pylelemmatize's
# similarity mapping takes seconds), so loading it is instant: python -m dre.default_mapping > default_mapping.py
# regenerates this file.
import string
import unicodedata
from functools import lru_cache

from pylelemmatize.fast_mapper import LemmatizerBMP


def build_mapping() -> dict[str, str]:
    from pylelemmatize import Charsets  # only needed to regenerate MAPPING
    alphabet = sorted(set(Charsets().mufibmp) | set(string.printable))
    letters = "".join(c for c in alphabet if unicodedata.category(c).startswith("L"))
    similar = LemmatizerBMP.from_alphabet_mapping(src_alphabet_str=letters, dst_alphabet_str=string.ascii_lowercase)
    mapping = {}
    for c in alphabet:
        category = unicodedata.category(c)
        if c.isspace() or category.startswith("Z"):
            mapping[c] = " "
        elif c == "-":
            mapping[c] = "-"
        elif c.isdecimal():
            mapping[c] = str(unicodedata.decimal(c))
        elif category.startswith("L") and similar(c) in string.ascii_lowercase:
            mapping[c] = similar(c)
        elif category[0] in "PS":
            mapping[c] = "."
    return mapping


@lru_cache(maxsize=1)
def default_mapper() -> LemmatizerBMP:
    return LemmatizerBMP(mapping_dict=MAPPING)


@lru_cache(maxsize=1)
def identity_mapper() -> LemmatizerBMP:
    # Keeps every character of the Basic Multilingual Plane as it is (case, punctuation, diacritics): no normalization.
    # Only characters outside it, which pylelemmatize does not map, become unknown.
    return LemmatizerBMP(mapping_dict={chr(c): chr(c) for c in range(1, 0x10000) if not 0xD800 <= c < 0xE000})


